-- 装置マスタ.カラム情報に連携コード1, 連携コード2を追加
UPDATE sys_master_define
SET column_info = '{"fields": [{"type": "string", "alias": "name", "title": "装置名", "locked": "true", "validation": {"required": "true", "maxlength": 40}, "physical_name": "machine_name"}, {"type": "string", "title": "製造番号", "editable": "true", "validation": {"required": "true", "maxlength": 8}, "physical_name": "machine_serial"}, {"type": "combo1", "title": "型式", "editable": "false", "physical_name": "machine_type_cd"}, {"type": "modal", "title": "詳細"}, {"type": "combo1", "title": "通信種別", "editable": "false", "physical_name": "com_type"}, {"type": "string", "title": "通信フォーマット", "editable": "false", "physical_name": "com_format_cd"}, {"type": "inet", "title": "IPアドレス", "editable": "true", "physical_name": "ip_address"}, {"type": "string", "title": "ポート", "editable": "true", "physical_name": "port"}, {"type": "number", "title": "ポート", "hidden": "true", "defaultValue": "", "validation": {"max": 65535, "min": 0}, "physical_name": "port"}, {"type": "string", "title": "バージョン", "hidden": "false", "validation": {"maxlength": 20},  "physical_name": "version"}, {"type": "string", "alias": null, "title": "連携コード1", "format": null, "hidden": "false", "locked": "false", "editable": "true", "validation": {"max": null, "min": null, "required": "false", "maxlength": "20"}, "physical_name": "in_hospital_cd_1"}, {"type": "string", "alias": null, "title": "連携コード2", "format": null, "hidden": "false", "locked": "false", "editable": "true", "validation": {"max": null, "min": null, "required": "false", "maxlength": "20"}, "physical_name": "in_hospital_cd_2"}, {"type": "disp", "title": "削除", "physical_name": "is_disp"}, {"type": "string", "title": "型式", "hidden": "true", "validation": {"required": "true"}, "physical_name": "machine_type_cd"}, {"type": "string", "hidden": "true", "physical_name": "facility_cd"}, {"type": "number", "alias": "code", "hidden": "true", "physical_name": "machine_no"}, {"type": "combo1", "title": "デバイスエッジ", "hidden": "true", "physical_name": "device_edge_no"}, {"type": "combo1", "hidden": "true", "physical_name": "is_ftp"}, {"type": "number", "hidden": "true", "physical_name": "is_va"}, {"type": "json", "hidden": "true", "physical_name": "machine_option"}, {"type": "date", "hidden": "true", "physical_name": "setting_date"}, {"type": "date", "hidden": "true", "physical_name": "delete_date"}, {"type": "string", "hidden": "true", "physical_name": "is_support_hd"}, {"type": "string", "hidden": "true", "physical_name": "is_support_ecum"}, {"type": "string", "hidden": "true", "physical_name": "is_support_hdf"}, {"type": "string", "hidden": "true", "physical_name": "is_support_hf"}, {"type": "string", "hidden": "true", "physical_name": "is_support_hd_ho"}, {"type": "string", "hidden": "true", "physical_name": "is_support_ecum_ho"}, {"type": "string", "hidden": "true", "physical_name": "is_support_afbf"}, {"type": "string", "hidden": "true", "physical_name": "is_support_ohdf"}, {"type": "string", "hidden": "true", "physical_name": "is_support_ohf"}, {"type": "string", "hidden": "true", "physical_name": "is_support_i_hdf"}, {"type": "string", "hidden": "true", "physical_name": "is_support_blood_purify"}, {"type": "number", "hidden": "true", "physical_name": "tmp_center_hd"}, {"type": "number", "hidden": "true", "physical_name": "tmp_center_ecum"}, {"type": "number", "hidden": "true", "physical_name": "tmp_center_hdf"}, {"type": "number", "hidden": "true", "physical_name": "tmp_center_hf"}, {"type": "number", "hidden": "true", "physical_name": "tmp_center_hd_ho"}, {"type": "number", "hidden": "true", "physical_name": "tmp_center_ohdf"}, {"type": "number", "hidden": "true", "physical_name": "tmp_center_ohf"}, {"type": "string", "hidden": "true", "physical_name": "memo"}, {"type": "del", "title": "削除", "physical_name": "is_del"}, {"type": "number", "hidden": "true", "defaultValue": "5", "physical_name": "blood_purify_type"}, {"type": "number", "hidden": "true", "defaultValue": "1", "physical_name": "is_blood_purify_use"}]}',
    up_date = CURRENT_TIMESTAMP
WHERE master_physical_name = 'mst_machine';
